using Engine.Mathematics;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System;
using System.Diagnostics.CodeAnalysis;
using System.Globalization;

namespace Engine.MathematicsTests
{
    [ExcludeFromCodeCoverage]
    [TestClass]
    [OSCondition(OperatingSystems.Windows)]
    public class BoundingSphereTests
    {
        public TestContext TestContext { get; set; }

        private static void AssertVector(Vector3 e, Vector3 a)
        {
            Assert.AreEqual(e.X, a.X, 1e-5f); Assert.AreEqual(e.Y, a.Y, 1e-5f); Assert.AreEqual(e.Z, a.Z, 1e-5f);
        }

        [TestMethod] public void ConstructorAndStateTest() { var s = new BoundingSphere(new Vector3(2, -3, 4), 5f); AssertVector(new Vector3(2, -3, 4), s.Center); Assert.AreEqual(5f, s.Radius, 1e-6f); s.Center = Vector3.One; s.Radius = 7f; AssertVector(Vector3.One, s.Center); Assert.AreEqual(7f, s.Radius, 1e-6f); BoundingSphere d = default; AssertVector(Vector3.Zero, d.Center); Assert.AreEqual(0f, d.Radius); }
        [TestMethod] public void RayIntersectsTest() { var s = new BoundingSphere(Vector3.Zero, 1f); Ray outward = new(new Vector3(-3, 0, 0), Vector3.UnitX); Assert.IsTrue(s.Intersects(ref outward)); Assert.IsTrue(s.Intersects(ref outward, out float d)); Assert.AreEqual(2f, d, 1e-5f); Assert.IsTrue(s.Intersects(ref outward, out _, out Vector3 p)); AssertVector(new Vector3(-1, 0, 0), p); Ray miss = new(new Vector3(0, 2, 0), Vector3.UnitX); Assert.IsFalse(s.Intersects(ref miss)); Assert.IsFalse(s.Intersects(ref miss, out d)); Assert.AreEqual(0f, d); Assert.IsFalse(s.Intersects(ref miss, out _, out p)); AssertVector(Vector3.Zero, p); Ray inside = new(Vector3.Zero, Vector3.UnitX); Assert.IsTrue(s.Intersects(ref inside, out d, out p)); Assert.AreEqual(0f, d, 1e-5f); AssertVector(Vector3.Zero, p); }
        [TestMethod]
        public void PlaneIntersectsTest()
        {
            var s = new BoundingSphere(Vector3.Zero, 1f);
            Plane behind = new(Vector3.UnitX, -2f);
            Assert.AreEqual(PlaneIntersectionType.Front, s.Intersects(ref behind));
            Plane front = new(Vector3.UnitX, 2f);
            Assert.AreEqual(PlaneIntersectionType.Back, s.Intersects(ref front));
            Plane back = new(-Vector3.UnitX, 2f);
            Assert.AreEqual(PlaneIntersectionType.Back, s.Intersects(ref back));
        }
        [TestMethod] public void TriangleIntersectsTest() { var s = new BoundingSphere(Vector3.Zero, 1f); var a = new Vector3(-2, -2, 0); var b = new Vector3(2, -2, 0); var c = new Vector3(0, 2, 0); Assert.IsTrue(s.Intersects(ref a, ref b, ref c)); var far1 = new Vector3(3, 0, 0); var far2 = new Vector3(4, 1, 0); var far3 = new Vector3(4, -1, 0); Assert.IsFalse(s.Intersects(ref far1, ref far2, ref far3)); var deg1 = Vector3.Zero; var deg2 = Vector3.UnitX; Assert.IsTrue(s.Intersects(ref deg1, ref deg2, ref deg1)); }
        [TestMethod] public void BoxIntersectsTest() { var s = new BoundingSphere(Vector3.Zero, 1f); var box = new BoundingBox(new Vector3(-.5f), new Vector3(.5f)); Assert.IsTrue(s.Intersects(box)); Assert.IsTrue(s.Intersects(ref box)); var disjoint = new BoundingBox(new Vector3(3), new Vector3(4)); Assert.IsFalse(s.Intersects(disjoint)); Assert.IsFalse(s.Intersects(ref disjoint)); var tangent = new BoundingBox(new Vector3(1, -1, -1), new Vector3(2, 1, 1)); Assert.IsTrue(s.Intersects(tangent)); }
        [TestMethod] public void SphereIntersectsTest() { var s = new BoundingSphere(Vector3.Zero, 1f); var overlap = new BoundingSphere(new Vector3(1.5f, 0, 0), 1f); Assert.IsTrue(s.Intersects(overlap)); Assert.IsTrue(s.Intersects(ref overlap)); var disjoint = new BoundingSphere(new Vector3(3, 0, 0), 1f); Assert.IsFalse(s.Intersects(disjoint)); Assert.AreEqual(ContainmentType.Disjoint, s.Contains(ref disjoint)); var inside = new BoundingSphere(Vector3.Zero, .25f); Assert.IsTrue(s.Intersects(inside)); }
        [TestMethod] public void ContainsPointTest() { var s = new BoundingSphere(new Vector3(2, -3, 4), 5f); var center = s.Center; Assert.AreEqual(ContainmentType.Contains, s.Contains(ref center)); var boundary = new Vector3(7, -3, 4); Assert.AreEqual(ContainmentType.Contains, s.Contains(ref boundary)); var outside = new Vector3(8, -3, 4); Assert.AreEqual(ContainmentType.Disjoint, s.Contains(ref outside)); var inside = new Vector3(2, -2, 4); Assert.AreEqual(ContainmentType.Contains, s.Contains(ref inside)); }
        [TestMethod] public void ContainsTriangleTest() { var s = new BoundingSphere(Vector3.Zero, 2f); var a = new Vector3(-1, -1, 0); var b = new Vector3(1, -1, 0); var c = new Vector3(0, 1, 0); Assert.AreEqual(ContainmentType.Contains, s.Contains(ref a, ref b, ref c)); var d = new Vector3(3, 0, 0); Assert.AreNotEqual(ContainmentType.Contains, s.Contains(ref d, ref b, ref c)); var z = Vector3.Zero; Assert.AreEqual(ContainmentType.Contains, s.Contains(ref z, ref z, ref z)); }
        [TestMethod] public void ContainsBoxTest() { var s = new BoundingSphere(Vector3.Zero, 2f); var inside = new BoundingBox(new Vector3(-1), new Vector3(1)); Assert.AreEqual(ContainmentType.Contains, s.Contains(ref inside)); var outside = new BoundingBox(new Vector3(3), new Vector3(4)); Assert.AreEqual(ContainmentType.Disjoint, s.Contains(ref outside)); var partial = new BoundingBox(new Vector3(1, -1, -1), new Vector3(3, 1, 1)); Assert.AreEqual(ContainmentType.Intersects, s.Contains(ref partial)); }
        [TestMethod] public void ContainsSphereTest() { var s = new BoundingSphere(Vector3.Zero, 3f); var inside = new BoundingSphere(Vector3.Zero, 1f); Assert.AreEqual(ContainmentType.Contains, s.Contains(ref inside)); var equal = s; Assert.AreEqual(ContainmentType.Contains, s.Contains(ref equal)); var disjoint = new BoundingSphere(new Vector3(6, 0, 0), 1f); Assert.AreEqual(ContainmentType.Disjoint, s.Contains(ref disjoint)); var overlap = new BoundingSphere(new Vector3(4, 0, 0), 2f); Assert.AreEqual(ContainmentType.Intersects, s.Contains(ref overlap)); }
        [TestMethod] public void FromPointsRangeTest() { var p = new[] { new Vector3(-100, 0, 0), new Vector3(-1, -1, -1), new Vector3(1, -1, -1), new Vector3(1, 1, 1), new Vector3(-1, 1, 1), new Vector3(100, 0, 0) }; BoundingSphere.FromPoints(p, 1, 4, out var r); AssertVector(Vector3.Zero, r.Center); Assert.AreEqual(MathF.Sqrt(3f), r.Radius, 1e-5f); Assert.ThrowsExactly<ArgumentNullException>(() => BoundingSphere.FromPoints(null, 0, 0, out _)); Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => BoundingSphere.FromPoints(p, -1, 1, out _)); Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => BoundingSphere.FromPoints(p, 0, -1, out _)); Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => BoundingSphere.FromPoints(p, 4, 3, out _)); }
        [TestMethod] public void FromPointsTest() { var p = new[] { new Vector3(-1, -1, -1), new Vector3(1, 1, 1) }; BoundingSphere.FromPoints(p, out var outS); var s = BoundingSphere.FromPoints(p); Assert.AreEqual(outS, s); AssertVector(Vector3.Zero, s.Center); Assert.AreEqual(MathF.Sqrt(3f), s.Radius, 1e-5f); Assert.ThrowsExactly<ArgumentNullException>(() => BoundingSphere.FromPoints(null)); Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => BoundingSphere.FromPoints([])); BoundingSphere.FromPoints([new Vector3(7, -2, 4)], out outS); AssertVector(new Vector3(7, -2, 4), outS.Center); Assert.AreEqual(0f, outS.Radius); }
        [TestMethod] public void FromBoxTest() { var box = new BoundingBox(new Vector3(-1, -1, -1), new Vector3(1, 1, 1)); BoundingSphere.FromBox(ref box, out BoundingSphere refS); var s = BoundingSphere.FromBox(box); Assert.AreEqual(refS, s); AssertVector(Vector3.Zero, refS.Center); Assert.AreEqual(MathF.Sqrt(3f), refS.Radius, 1e-5f); var asymmetric = new BoundingBox(new Vector3(-2, 0, 1), new Vector3(4, 6, 9)); var a = BoundingSphere.FromBox(asymmetric); AssertVector(new Vector3(1, 3, 5), a.Center); Assert.AreEqual(MathF.Sqrt(36f + 36f + 64f) * 0.5f, a.Radius, 1e-5f); }
        [TestMethod] public void MergeRefAndValueTest() { var a = new BoundingSphere(new Vector3(-2, 0, 0), 1f); var b = new BoundingSphere(new Vector3(2, 0, 0), 1f); BoundingSphere.Merge(ref a, ref b, out var mr); var mv = BoundingSphere.Merge(a, b); Assert.AreEqual(mr, mv); AssertVector(Vector3.Zero, mr.Center); Assert.AreEqual(3f, mr.Radius, 1e-5f); var nested = new BoundingSphere(Vector3.Zero, 5f); var zero = new BoundingSphere(new Vector3(1, 0, 0), 0f); var n = BoundingSphere.Merge(nested, zero); AssertVector(Vector3.Zero, n.Center); Assert.AreEqual(5f, n.Radius, 1e-5f); }
        [TestMethod] public void TransformTest() { var s = new BoundingSphere(new Vector3(1, 2, 3), 2f); Assert.AreEqual(s, BoundingSphere.Transform(s, Matrix4x4.Identity)); var translated = BoundingSphere.Transform(s, Matrix4x4.Translation(10, -4, 2)); AssertVector(new Vector3(11, -2, 5), translated.Center); Assert.AreEqual(2f, translated.Radius, 1e-5f); var scaled = BoundingSphere.Transform(s, Matrix4x4.Scaling(2, 3, 4)); AssertVector(new Vector3(2, 6, 12), scaled.Center); Assert.AreEqual(8f, scaled.Radius, 1e-5f); }
        [TestMethod] public void NearEqualTest() { var a = new BoundingSphere(Vector3.Zero, 1f); var b = new BoundingSphere(new Vector3(.01f, 0, 0), 1.01f); Assert.IsTrue(BoundingSphere.NearEqual(a, b, .02f)); Assert.IsFalse(BoundingSphere.NearEqual(a, b, .005f)); Assert.IsTrue(BoundingSphere.NearEqual(a, a)); Assert.IsFalse(BoundingSphere.NearEqual(a, new BoundingSphere(Vector3.Zero, 2f), .5f)); }
        [TestMethod] public void EqualityAndHashTest() { var a = new BoundingSphere(Vector3.Zero, 1f); var b = new BoundingSphere(Vector3.Zero, 1f); var c = new BoundingSphere(Vector3.UnitX, 1f); Assert.IsTrue(a == b); Assert.IsFalse(a != b); Assert.IsTrue(a.Equals(b)); Assert.IsTrue(a.Equals(ref b)); Assert.IsTrue(a.Equals((object)b)); Assert.IsFalse(a.Equals((object)c)); Assert.IsFalse(a.Equals((object)null)); Assert.AreEqual(a.GetHashCode(), b.GetHashCode()); Assert.IsFalse(a == c); }
        [TestMethod] public void FormattingTest() { var s = new BoundingSphere(new Vector3(1.25f, -2.5f, 3f), 4.75f); var text = s.ToString(); Assert.Contains("Center:", text); Assert.Contains("Radius:", text); Assert.Contains("Center:", s.ToString("F1")); var en = CultureInfo.GetCultureInfo("en-US"); var fr = CultureInfo.GetCultureInfo("fr-FR"); Assert.AreNotEqual(s.ToString("F1", en), s.ToString("F1", fr)); Assert.IsNotNull(s.ToString(en)); Assert.IsNotNull(s.ToString("F2", en)); }
        [TestMethod] public void ValidationAndDefaultTest() { BoundingSphere d = default; AssertVector(Vector3.Zero, d.Center); Assert.AreEqual(0f, d.Radius); Assert.AreEqual(ContainmentType.Contains, d.Contains(ref d.Center)); Assert.ThrowsExactly<ArgumentNullException>(() => BoundingSphere.FromPoints((Vector3[])null, out _)); Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => BoundingSphere.FromPoints([Vector3.Zero], -1, 1, out _)); var neg = new BoundingSphere(Vector3.Zero, -1f); Assert.AreEqual(-1f, neg.Radius); }
    }
}